import functools


def 记一笔(fn):
    @functools.wraps(fn)
    def 包装(*args, **kwargs):
        print("开演啦")
        return fn(*args, **kwargs)

    return 包装


@记一笔
def double(n):
    return n * 2


print(double({n}))
